    Object.keys(ADMIN_EDITS.glossaryDates || {}).forEach((k) => { const v = ADMIN_EDITS.glossaryDates[k]; if (v) window.GLOSSARY_DATES[k] = v; else delete window.GLOSSARY_DATES[k]; });
